arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_fa2090f6249c4376a19d64e8d990ffe3.Models
@using sv_fa2090f6249c4376a19d64e8d990ffe3.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="@_channels"
                    SelectedChannelId="@_selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="main-area @(_threadOpen ? "" : "main-area-full")">
        @if (_selectedChannel is not null)
        {
            <div class="main-header">
                <h5># @_selectedChannel.Name</h5>
                <span class="channel-desc">@_selectedChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var message in _messages)
                {
                    <MessageItem Message="@message"
                                 ThreadReplyCount="@GetThreadReplyCount(message.Id)"
                                 OnOpenThread="OpenThread"
                                 OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="@($"Message #{_selectedChannel.Name}")"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="@_threadRootMessage"
                     Replies="@_threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadReplies = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = [];
    private Message? _threadRootMessage;
    private Channel? _selectedChannel;
    private int _selectedChannelId;
    private bool _threadOpen;
    private bool _loadingMore;
    private bool _allMessagesLoaded;
    private const int PageSize = 30;
    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _allMessagesLoaded = false;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary
        _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
            _threadRootMessage.Id,
            _threadReplies.Count,
            reply.SentAt);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistic update
        var idx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = _messages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                reactions[existing] = new Reaction(r.Emoji, [..r.Users, "You"]);
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            _messages[idx] = msg with { Reactions = reactions };
        }
    }

    private async Task HandleScroll()
    {
        // Pagination triggered by JS interop would be ideal, but for simplicity
        // we provide a "Load more" approach via scroll detection placeholder.
        // The actual scroll-to-top detection requires JS interop.
    }

    public async Task LoadOlderMessages()
    {
        if (_loadingMore || _allMessagesLoaded || _selectedChannel is null) return;
        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
        if (older.Count < PageSize) _allMessagesLoaded = true;
        _messages.InsertRange(0, older);

        _loadingMore = false;
        BuildThreadSummaries();
    }

    private void BuildThreadSummaries()
    {
        // Build summaries from messages that are replies
        var grouped = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value);

        _threadSummaries = grouped.ToDictionary(
            g => g.Key,
            g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)));
    }

    private int GetThreadReplyCount(int messageId) =>
        _threadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;
}

/* ===== Chat Layout ===== */
.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d42;
    color: #edf2f4;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1a1b2e;
}

::deep .sidebar-header {
    padding: 1rem;
    border-bottom: 1px solid #3d3f5c;
}

::deep .sidebar-header h5 {
    margin: 0;
    font-weight: 600;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

::deep .channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #3d3f5c;
}

::deep .channel-item.active {
    background: #4361ee;
}

::deep .channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

::deep .unread-badge {
    background: #ef233c;
    color: white;
    border-radius: 10px;
    padding: 0 0.5rem;
    font-size: 0.75rem;
    font-weight: 600;
    min-width: 20px;
    text-align: center;
}

::deep .channel-description {
    font-size: 0.8rem;
    color: #8d99ae;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ===== Main Area ===== */
.main-area {
    width: 55%;
    display: flex;
    flex-direction: column;
    background: #fff;
    transition: width 0.2s ease;
}

.main-area-full {
    width: 80%;
}

.main-header {
    padding: 0.75rem 1.25rem;
    border-bottom: 1px solid #dee2e6;
    background: #f8f9fa;
}

.main-header h5 {
    margin: 0;
    font-weight: 600;
}

.channel-desc {
    font-size: 0.85rem;
    color: #6c757d;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #6c757d;
    font-size: 0.85rem;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6c757d;
}

/* ===== Message Item ===== */
::deep .message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    margin-bottom: 0.25rem;
    position: relative;
    transition: background 0.15s;
}

::deep .message-item:hover {
    background: #f0f1f3;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

::deep .message-author {
    font-size: 0.95rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #8d99ae;
}

::deep .message-content {
    font-size: 0.95rem;
    line-height: 1.45;
    color: #333;
}

::deep .reaction-bar {
    display: flex;
    gap: 0.35rem;
    margin-top: 0.35rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #e9ecef;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    padding: 0.1rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #d0d3d9;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #4361ee;
    font-size: 0.82rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.15rem;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: 0.25rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.15rem 0.25rem;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}

::deep .action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    padding: 0.15rem 0.35rem;
    border-radius: 4px;
    transition: background 0.15s;
}

::deep .action-btn:hover {
    background: #e9ecef;
}

::deep .emoji-picker {
    display: flex;
    gap: 0.25rem;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 0.35rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
    margin-top: 0.25rem;
    width: fit-content;
}

::deep .emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 4px;
    transition: background 0.15s;
}

::deep .emoji-option:hover {
    background: #e9ecef;
}

/* ===== Message Input ===== */
::deep .message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1.25rem;
