+            _threadReplies.Count,
+            reply.SentAt);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistic update
+        var idx = _messages.FindIndex(m => m.Id == args.MessageId);
+        if (idx >= 0)
+        {
+            var msg = _messages[idx];
+            var reactions = msg.Reactions.ToList();
+            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
+            if (existing >= 0)
+            {
+                var r = reactions[existing];
+                reactions[existing] = new Reaction(r.Emoji, [..r.Users, "You"]);
+            }
+            else
+            {
+                reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+            _messages[idx] = msg with { Reactions = reactions };
+        }
+    }
+
+    private async Task HandleScroll()
+    {
+        // Pagination triggered by JS interop would be ideal, but for simplicity
+        // we provide a "Load more" approach via scroll detection placeholder.
+        // The actual scroll-to-top detection requires JS interop.
+    }
+
+    public async Task LoadOlderMessages()
+    {
+        if (_loadingMore || _allMessagesLoaded || _selectedChannel is null) return;
+        _loadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
+        if (older.Count < PageSize) _allMessagesLoaded = true;
+        _messages.InsertRange(0, older);
+
+        _loadingMore = false;
+        BuildThreadSummaries();
+    }
+
+    private void BuildThreadSummaries()
+    {
+        // Build summaries from messages that are replies
+        var grouped = _messages
+            .Where(m => m.ReplyToId is not null)
+            .GroupBy(m => m.ReplyToId!.Value);
+
+        _threadSummaries = grouped.ToDictionary(
+            g => g.Key,
+            g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)));
+    }
+
+    private int GetThreadReplyCount(int messageId) =>
+        _threadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;
+}
+

